<?php

declare(strict_types=1);

namespace YouWillLikeIT\Cleaning\DataObjects;

use SilverStripe\ORM\DataObject;
use SilverStripe\Security\Member;
use SilverStripe\Security\Permission;

/**
 * Location-proof check-in via Revir QR scan.
 *
 * Distinct from TimeTracking (which tracks work hours).
 * RevirCheckIn records that a worker physically scanned the
 * QR code posted at the revir — providing proof of presence.
 *
 * One QR token per Revir, static (no expiry), stored on the Revir.
 * Token is generated by BuildDefaultGroupsTask or admin action.
 */
class RevirCheckIn extends DataObject
{
    private static string $table_name    = 'RevirCheckIn';
    private static string $singular_name = 'Revir Check-In';
    private static string $plural_name   = 'Revir Check-Ins';

    /** @var array<string,string> */
    private static array $db = [
        'ScannedAt'  => 'Datetime',
        'IPAddress'  => 'Varchar(45)',
        'UserAgent'  => 'Varchar(512)',
        'Latitude'   => 'Decimal(9,6)',
        'Longitude'  => 'Decimal(9,6)',
        'QRToken' => 'Varchar(64)',
    ];

    /** @var array<string,string> */
    private static array $has_one = [
        'Worker'     => Member::class,
        'Revir'      => Revir::class,
        'Assignment' => WorkerAssignment::class,
    ];

    /** @var array<string,string> */
    private static array $summary_fields = [
        'ScannedAt'    => 'Scanned At',
        'Worker.Name'  => 'Worker',
        'Revir.Name'   => 'Revir',
        'IPAddress'    => 'IP',
    ];

    private static string $default_sort = 'ScannedAt DESC';

    // ── Permissions ───────────────────────────────────────────────────────

    public function canView(mixed $member = null): bool
    {
        return Permission::checkMember($member, ['SUPER_ADMIN', 'COMPANY_ADMIN', 'AREA_MANAGER', 'ADMIN']);
    }

    public function canEdit(mixed $member = null): bool   { return false; }
    public function canDelete(mixed $member = null): bool { return Permission::checkMember($member, 'SUPER_ADMIN'); }
    public function canCreate(mixed $member = null, $context = []): bool { return false; }
}
